import sqlite3
for db in ('state.db','verification_evidence.db','shared-state.db'):
    try:
        c=sqlite3.connect(f'file:{db}?mode=ro',uri=True)
        tabs=[r[0] for r in c.execute("select name from sqlite_master where type='table'")]
        hits=[t for t in tabs if 'tele' in t or 'event' in t or 'browser' in t]
        print(db, '| telemetry-ish tables:', hits)
    except Exception as e:
        print(db,'ERR',e)
EOF"}

